// Logos e cores institucionais dos bancos, embutidos como data URLs para uso em PDFs.
// Gerado a partir de src/assets/brand — não editar manualmente.

export interface BancoBrand {
  cor: string;
  logo: string;
  ratio: number; // largura / altura da imagem
}

const LOGO_BRADESCO =
  "data:image/png;base64,";

const LOGO_ITAU = "/__l5e/assets-v1/88123484-ea95-445b-9bb3-1844a6ba21ee/itau-logo-2023.png"; // Official Itaú 2023 logo
  "data:image/png;base64,";

const LOGO_SANTANDER =
  "data:image/png;base64,";

export const BANCO_BRANDS: Record<string, BancoBrand> = {
  bradesco: { cor: "#CC092F", logo: LOGO_BRADESCO, ratio: 1 },
  itau: { cor: "#EC7000", logo: LOGO_ITAU, ratio: 1 },
  santander: { cor: "#EC0000", logo: LOGO_SANTANDER, ratio: 1.85 },
};

/** Normaliza o nome do banco vindo da API para uma chave conhecida. */
export function resolveBancoBrand(nome: string | null | undefined): BancoBrand | null {
  if (!nome) return null;
  const n = nome
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
  if (n.includes("bradesco")) return BANCO_BRANDS.bradesco;
  if (n.includes("itau")) return BANCO_BRANDS.itau;
  if (n.includes("santander")) return BANCO_BRANDS.santander;
  return null;
}
